class Solution {
    private int result = 0;
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public int uniquePathsIII(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int sr = 0, sc = 0, empty = 1;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) { sr = i; sc = j; }
                else if (grid[i][j] == 0) empty++;
            }
        dfs(grid, sr, sc, empty, m, n);
        return result;
    }
    private void dfs(int[][] grid, int r, int c, int remaining, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == -1) return;
        if (grid[r][c] == 2) { if (remaining == 0) result++; return; }
        grid[r][c] = -1;
        for (int[] d : dirs) dfs(grid, r + d[0], c + d[1], remaining - 1, m, n);
        grid[r][c] = 0;
    }
}
